  "cmp.title":"Vergleich","cmp.typical":"Typischer Gratis-Scanner","cmp.r1":"Wohin die Fotos gehen","cmp.r1a":"auf den Server des Dienstes","cmp.r1b":"bleiben im Browser","cmp.r2":"Wasserzeichen","cmp.r2a":"oft","cmp.r2b":"nein","cmp.r3":"Ergebnis","cmp.r3a":"oft nur „Kopieren“","cmp.r3b":"DOCX, PDF, MD, TXT","cmp.r5":"Handschrift & Tabellen","cmp.r5a":"schwach","cmp.r5b":"Handschrift & Tabellen Pro",
